import { tags } from "typia";

/**
 * Seller dashboard summary containing aggregated shop performance metrics. Provides sellers with an overview of their product catalog size, total order volume, and pending actions requiring attention (cancellation and refund requests awaiting response). This is a computed response type, not a direct database entity.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ISellerDashboard = {
  /**
   * Total number of active products listed by the seller, excluding soft-deleted products.
   *
   * @x-autobe-specification COUNT(*) from shopping_mall_products WHERE shopping_seller_id = authenticated_seller.id AND deleted = false. Returns 0 when seller has no active products.
   */
  productCount: number & tags.Type<"int32">;

  /**
   * Total number of order items across all orders containing the seller's products.
   *
   * @x-autobe-specification COUNT(*) from shopping_mall_order_items WHERE shopping_mall_seller_id = authenticated_seller.id. Counts all order items containing the seller's products regardless of order status. Returns 0 when no orders exist.
   */
  orderItemCount: number & tags.Type<"int32">;

  /**
   * Number of customer cancellation requests awaiting seller response (status = PENDING).
   *
   * @x-autobe-specification COUNT(*) from shopping_mall_cancellation_requests WHERE responded_by_seller_id = authenticated_seller.id AND status = 'PENDING'. Returns 0 when no pending cancellation requests exist.
   */
  pendingCancellationCount: number & tags.Type<"int32">;

  /**
   * Number of customer refund requests awaiting seller response (status = PENDING).
   *
   * @x-autobe-specification COUNT(*) from shopping_mall_refund_requests WHERE responded_by_seller_id = authenticated_seller.id AND status = 'PENDING'. Returns 0 when no pending refund requests exist.
   */
  pendingRefundCount: number & tags.Type<"int32">;
};
